    Bug 1970796 - Package pdfjs default prefs and enable signature editor. r=babolivier

    Differential Revision: https://phabricator.services.mozilla.com/D257021

diff --git a/mail/app/profile/all-thunderbird.js b/mail/app/profile/all-thunderbird.js
index 4b6c56dbed8..388eef963a1 100644
--- a/mail/app/profile/all-thunderbird.js
+++ b/mail/app/profile/all-thunderbird.js
@@ -1386,6 +1386,9 @@ pref("pdfjs.firstRun", true);
 pref("pdfjs.previousHandler.preferredAction", 0);
 pref("pdfjs.previousHandler.alwaysAskBeforeHandling", false);

+// Enable signatures in PDF.js viewer in Thunderbird.
+pref("pdfjs.enableSignatureEditor", true);
+
 pref("mail.activity.loglevel", "Warn");

 // The number of public recipients before we offer BCC addressing.
diff --git a/mail/installer/package-manifest.in b/mail/installer/package-manifest.in
index 372a89a2d5e..789a13f0c37 100644
--- a/mail/installer/package-manifest.in
+++ b/mail/installer/package-manifest.in
@@ -195,6 +195,7 @@
 @RESPATH@/chrome/messenger.manifest
 @RESPATH@/chrome/pdfjs.manifest
 @RESPATH@/chrome/pdfjs/*
+@RESPATH@/defaults/pref/PdfJsDefaultPrefs.js
 #ifndef XP_UNIX
 @RESPATH@/chrome/icons/default/messengerWindow.ico
 @RESPATH@/chrome/icons/default/msgcomposeWindow.ico
